#![no_std]
#![forbid(unsafe_code)]
use chacha20poly1305::{aead::AeadInOut, ChaCha20Poly1305, KeyInit};
use ed25519_dalek::{Signature, VerifyingKey};
pub fn compile_aead_open(key: &[u8; 32], nonce: &[u8; 12], ad: &[u8], buffer: &mut [u8], tag: &[u8; 16]) -> bool {
    ChaCha20Poly1305::new(key.into()).decrypt_inout_detached(nonce.into(), ad, buffer.into(), tag.into()).is_ok()
}
pub fn compile_signature_verify(public: &[u8; 32], signature: &[u8; 64], message: &[u8]) -> bool {
    VerifyingKey::from_bytes(public).map(|key| key.verify_strict(message, &Signature::from_bytes(signature)).is_ok()).unwrap_or(false)
}
